tch={}Hub.Engines.InMatch=InMatch do local lastAbilityTick=0 local lastUpgradeTick=0 local lastPlaceTick=0 local lastLoadoutTick=0 local myUnitsCache={}local waypointsCache=nil local placedBySlot={}local function resetMatchState()Flags._votedStart=false Flags._setDifficulty=false Flags._leftThisMatch=false Flags._soldFarms=false Flags._prioritized={}waypointsCache=nil placedBySlot={}end local function listToSet(arr)local s={}for _,v in ipairs(arr or{})do s[tostring(v)]=true end return s end local function findNearestUnit(pos,maxDist)maxDist=maxDist or 3 local best,bestD=nil,maxDist for _,u in ipairs(myUnitsCache)do local cf=GameAPI.getUnitPosition(u.model)if cf then local d=(cf.Position-pos).Magnitude if d<bestD then best,bestD=u,d end end end return best end InMatch.findNearestUnit=findNearestUnit local function isFarmUnit(u)return GameAPI.isFarmUnitName(u.name)or GameAPI.isFarmUnitName(u.id)end local function sortForUpgrade(units,wave)local list={}local maxCap=Config.MaxUpgradeLevel or 0 for _,u in ipairs(units)do if not GameAPI.isUnitMaxed(u.model)then if maxCap<=0 or(tonumber(u.upgrade)or 0)<maxCap then table.insert(list,u)end end end local mode=Config.UpgradeStrategy if mode=="Smart Economy"then local dpsCount=0 for _,u in ipairs(units)do if not isFarmUnit(u)then dpsCount=dpsCount+1 end end table.sort(list,function(a,b)local aFarm=isFarmUnit(a)local bFarm=isFarmUnit(b)local aUp=tonumber(a.upgrade)or 0 local bUp=tonumber(b.upgrade)or 0 local aCost=GameAPI.getUnitCost(a.model)local bCost=GameAPI.getUnitCost(b.model)if dpsCount>=1 and(wave or 0)<10 then local aEcoPrio=aFarm and aUp<4 local bEcoPrio=bFarm and bUp<4 if aEcoPrio~=bEcoPrio then return aEcoPrio end elseif(wave or 0)>=10 then if aFarm~=bFarm then return not aFarm end end if aUp~=bUp then return aUp<bUp end return aCost<bCost end)elseif mode=="Balanced Level"then table.sort(list,function(a,b)local aUp=tonumber(a.upgrade)or 0 local bUp=tonumber(b.upgrade)or 0 if aUp~=bUp then return aUp<bUp end return GameAPI.getUnitCost(a.model)<GameAPI.getUnitCost(b.model)end)elseif mode=="Carry First"then table.sort(list,function(a,b)local aFarm=isFarmUnit(a)and 1 or 0 local bFarm=isFarmUnit(b)and 1 or 0 if aFarm~=bFarm then return aFarm<bFarm end local aUp=tonumber(a.upgrade)or 0 local bUp=tonumber(b.upgrade)or 0 if aUp~=bUp then return aUp<bUp end return GameAPI.getUnitCost(a.model)>GameAPI.getUnitCost(b.model)end)elseif mode=="Farm First"then table.sort(list,function(a,b)local an=isFarmUnit(a)and 0 or 1 local bn=isFarmUnit(b)and 0 or 1 if an==bn then return GameAPI.getUnitCost(a.model)<GameAPI.getUnitCost(b.model)end return an<bn end)elseif mode=="Cheapest First"then table.sort(list,function(a,b)return GameAPI.getUnitCost(a.model)<GameAPI.getUnitCost(b.model)end)elseif mode=="Highest Cost"then table.sort(list,function(a,b)return GameAPI.getUnitCost(a.model)>GameAPI.getUnitCost(b.model)end)end return list end InMatch.sortForUpgrade=sortForUpgrade local function trySmartPlace(wave,money)local slots=GameAPI.getEquippedSlots()if#slots==0 then return false end if tick()-lastLoadoutTick>2 then lastLoadoutTick=tick()local desc={}for _,s in ipairs(slots)do table.insert(desc,"#"..s.slot.." "..s.name..(s.isFarm and"[F]"or"").." ("..s.placed.."/"..s.maxPlace..")")end loadoutInfo:Set(table.concat(desc," | "))end if wave<(Config.PlaceStartWave or 1)then return false end local dpsSet=listToSet(Config.PlaceSlots)local farmSet=listToSet(Config.FarmSlots)local hillSet=listToSet(Config.HillSlots)local maxPer=Config.MaxUnitsPerSlot or 3 local dpsOnField=0 for _,u in ipairs(myUnitsCache)do if not isFarmUnit(u)then dpsOnField=dpsOnField+1 end end local dpsCandidates,farmCandidates={},{}for _,s in ipairs(slots)do local placed=math.max(s.placed or 0,placedBySlot[s.slot]or 0)local cap=math.min(s.maxPlace or 4,maxPer)if placed<cap and(s.cost or 0)<=money then local isFarmSlot=farmSet[s.slot]or(s.isFarm and not dpsSet[s.slot]and not hillSet[s.slot])local isHillSlot=hillSet[s.slot]==true local isDpsSlot